#!/usr/bin/env bash
set -euo pipefail
source "${BASH_SOURCE[0]%/*}/_render_job.bash"
declare -A render_job=()
render_job_into render_job "${1:-}" tmux colors.conf

render_output_is_current render_job && exit 0
render_stage_output_into render_job
trap 'rm -f -- "${render_job[staged_file]}"' EXIT

if [[ -n "${render_job[pack_override]}" ]]; then
  render_write_pack_override render_job
else
  render_read_palette_into render_job
  cat > "${render_job[staged_file]}" <<EOF
# Generated by render/tmux
set -g status-style "bg=${render_job[background_color]},fg=${render_job[foreground_color]}"
set -g window-status-current-style "bg=${render_job[color4]},fg=${render_job[background_color]},bold"
set -g window-status-style "bg=${render_job[background_color]},fg=${render_job[foreground_color]}"
set -g pane-active-border-style "fg=${render_job[color4]}"
set -g pane-border-style "fg=${render_job[color8]}"
set -g message-style "bg=${render_job[color8]},fg=${render_job[foreground_color]}"
set -g message-command-style "bg=${render_job[color8]},fg=${render_job[foreground_color]}"
set -g mode-style "bg=${render_job[color4]},fg=${render_job[background_color]}"
EOF
fi

render_commit_staged_output render_job
trap - EXIT
